#include <stdio.h>
#include <stdlib.h>

int *make_range(int from, int to, int *length) {
    int n = abs(to - from) + 1;
    int step = from <= to ? 1 : -1;
    int *a = malloc(n * sizeof *a);
    if (a == NULL) {
        return NULL;
    }
    for (int i = 0; i < n; i++) {
        a[i] = from + i * step;
    }
    *length = n;
    return a;
}

int main(void) {
    int from, to;
    scanf("%d %d", &from, &to);
    int length = 0;
    int *range = make_range(from, to, &length);
    if (range == NULL) {
        return 1;
    }
    printf("%d\n", length);
    for (int i = 0; i < length; i++) {
        printf(i + 1 < length ? "%d " : "%d\n", range[i]);
    }
    free(range);
    return 0;
}

