#include <stdio.h>
#include <stdlib.h>

int *merge(const int *a, int n, const int *b, int m) {
    int *out = malloc((n + m) * sizeof *out);
    if (out == NULL) {
        return NULL;
    }
    int i = 0, j = 0, k = 0;
    while (i < n && j < m) {
        if (a[i] <= b[j]) {
            out[k++] = a[i++];
        } else {
            out[k++] = b[j++];
        }
    }
    while (i < n) {
        out[k++] = a[i++];
    }
    while (j < m) {
        out[k++] = b[j++];
    }
    return out;
}

int *read_array(int *length) {
    scanf("%d", length);
    int *a = malloc(*length * sizeof *a);
    if (a == NULL) {
        return NULL;
    }
    for (int i = 0; i < *length; i++) {
        scanf("%d", &a[i]);
    }
    return a;
}

int main(void) {
    int n, m;
    int *a = read_array(&n);
    int *b = read_array(&m);
    int *c = (a && b) ? merge(a, n, b, m) : NULL;
    if (c != NULL) {
        for (int i = 0; i < n + m; i++) {
            printf(i + 1 < n + m ? "%d " : "%d\n", c[i]);
        }
    }
    free(a);
    free(b);
    free(c);
    return c == NULL;
}

