#include <stdlib.h>

int *make(int value) {
    int *p = malloc(sizeof *p);
    if (p != NULL) {
        *p = value * 2;
    }
    return p;
}

int main(void) {
    int *a = make(5);
    int *b = make(*a);
    if (a == NULL || b == NULL) {
        return 1;
    }
    printf("%d %d\n", *a, *b);
    free(a);
    free(b);
    return 0;
}

